O[6601] = "Görünüşe göre maskeli oyun sona erdi. Myranda the Hag'in senin için yarattığı Amulet of Draconic Subversion'ın Blackrock Spire içinde çalışmayacağını biliyorsun. Belki de Rexxar'ı bulup durumunu anlatmalısın. Ona Dull Drakefire Amulet'i göster. Umarım ne yapacağını bilir."
O[6602] = "Blackrock Spire'a git ve General Drakkisath'ı öldür. Kanını topla ve Rexxar'a getir."
O[6603] = "Winterspring'deki kaplıcaların yakınında Donova Snowden'ı bul."
