O[6606] = "Everlook'taki Witch Doctor Mau'ari ile konuş."
O[6608] = "Lumak'ın artık balık tutma becerini geliştirmene yardım edemeyeceğini söylemeye çalıştığını düşünüyorsun. Theramore'un güneyindeki adalardan birinde balık tutan bir insan olan arkadaşı Nat Pagle'ı bulmayı deneyebilirsin (en azından Lumak'ın dediği bu gibi görünüyor)."
O[6609] = "Kalimdor'a, kıyıdaki Theramore şehrine git. Oradan ana kasabanın güneyindeki bir adayı ara. Nat Pagle seni bekliyor!"
